import os, json, re
import numpy as np

def _is_gamma_json(obj):
    if not isinstance(obj, dict): return False
    for k in ("gamma", "gamma_profile", "gamma_t", "gamma_values"):
        v = obj.get(k, None)
        if isinstance(v, (list, tuple)) and len(v) in (32,):
            return True
    # occasional nested storage
    if "params" in obj and isinstance(obj["params"], dict):
        v = obj["params"].get("gamma", None)
        if isinstance(v, (list, tuple)) and len(v) in (32,):
            return True
    return False

def _extract_gamma(obj):
    for k in ("gamma", "gamma_profile", "gamma_t", "gamma_values"):
        v = obj.get(k, None)
        if isinstance(v, (list, tuple)):
            arr = np.array(v, dtype=float)
            if arr.ndim == 1 and arr.size == 32:
                return arr
    if "params" in obj and isinstance(obj["params"], dict):
        v = obj["params"].get("gamma", None)
        if isinstance(v, (list, tuple)):
            arr = np.array(v, dtype=float)
            if arr.ndim == 1 and arr.size == 32:
                return arr
    return None

def _is_percond_json(obj):
    if not isinstance(obj, dict): return False
    cand = None
    if "per_condition_step_mae" in obj: cand = obj["per_condition_step_mae"]
    elif "val_mae_by_condition" in obj: cand = obj["val_mae_by_condition"]
    if isinstance(cand, dict):
        # at least one condition has a length-32 list
        for v in cand.values():
            if isinstance(v, (list, tuple)) and len(v) == 32:
                return True
    return False

def _extract_percond(obj):
    if "per_condition_step_mae" in obj:
        cand = obj["per_condition_step_mae"]
    elif "val_mae_by_condition" in obj:
        cand = obj["val_mae_by_condition"]
    else:
        return {}
    out = {}
    for ck, v in cand.items():
        arr = np.array(v, dtype=float)
        if arr.ndim == 1 and arr.size == 32 and not np.isnan(arr).any():
            out[str(ck)] = arr
    return out

def test():
    base_dir = "storage/ariadne/analyses"
    T = 32
    gamma_list = []
    percond_list = []
    # recursive scan
    for root, _, files in os.walk(base_dir):
        for fn in files:
            if not fn.endswith(".json"): continue
            path = os.path.join(root, fn)
            try:
                with open(path, "r") as f:
                    obj = json.load(f)
            except Exception:
                continue
            if _is_gamma_json(obj):
                g = _extract_gamma(obj)
                if g is not None and g.size == T:
                    gamma_list.append((path, g))
            if _is_percond_json(obj):
                pc = _extract_percond(obj)
                if pc:
                    percond_list.append((path, pc))

    summary = {
        "gamma_files": len(gamma_list),
        "per_condition_files": len(percond_list),
        "base_dir": base_dir,
    }

    if not gamma_list or not percond_list:
        out = {"ok": False, "reason": "Insufficient files", **summary}
    else:
        G = np.vstack([g for _, g in gamma_list])        # (S,T)
        gamma_mean = G.mean(axis=0)
        gamma_std  = G.std(axis=0)

        # Merge per-condition across all files by keyed union
        cond_acc = {}
        for _, pc in percond_list:
            for ck, arr in pc.items():
                cond_acc.setdefault(ck, []).append(arr)
        cond_stats = {}
        for ck, lst in cond_acc.items():
            M = np.vstack(lst)
            if M.shape[1] != T or np.isnan(M).any(): continue
            cond_stats[ck] = {
                "mean": M.mean(axis=0).tolist(),
                "std":  M.std(axis=0).tolist(),
                "count": int(M.shape[0]),
            }

        # Overall step difficulty
        if cond_stats:
            step_mae_mean = np.vstack([np.array(v["mean"]) for v in cond_stats.values()]).mean(axis=0)
        else:
            step_mae_mean = np.full((T,), np.nan)

        def safe_corr(a, b):
            a = np.asarray(a, dtype=float); b = np.asarray(b, dtype=float)
            if np.isnan(a).any() or np.isnan(b).any(): return None
            if a.std() == 0 or b.std() == 0: return None
            return float(np.corrcoef(a, b)[0,1])

        corr_gamma_vs_mean = safe_corr(gamma_mean, step_mae_mean)

        # heuristic potential alignment score
        def z(x): x=np.asarray(x,dtype=float); return (x-x.mean())/(x.std()+1e-8)
        potential = None if np.isnan(step_mae_mean).any() else float(np.dot(-z(gamma_mean), z(step_mae_mean))/T)

        out = {
            "ok": True,
            **summary,
            "gamma_mean": gamma_mean.tolist(),
            "gamma_std": gamma_std.tolist(),
            "corr_gamma_vs_step_mae_mean": corr_gamma_vs_mean,
            "potential_alignment_score": potential,
            "conditions_analyzed": {k: {"count": v["count"]} for k,v in cond_stats.items()},
        }

    out_path = os.path.join(base_dir, "cond_gamma_correlation_v2.json")
    with open(out_path, "w") as f:
        json.dump(out, f, indent=2)
    print("Analysis v2 complete ->", out_path)
    return "OK"
